<summary>Prototype diff (against <code>fac8d4a9</code>)</summary>

```diff
--- a/transformer_engine/pytorch/csrc/quantizer.cpp
+++ b/transformer_engine/pytorch/csrc/quantizer.cpp
@@ -2063,7 +2063,13 @@
     // nvte_compute_amax_with_config will zero out the pointer if needed
     const int64_t amax_cols = row_scaled_nvfp4 ? static_cast<int64_t>(flat_last_dim) : 1;
     if (!disable_second_level_scale) {
-      amax_columnwise = at::empty({amax_cols}, bit32_tensor_opts);
+      // PROTOTYPE (review of #3750): with a single amax (no RHT, no row scaling), the
+      // column-wise amax aliases the row-wise one, so quantize_impl skips the copy.
+      if (rowwise_usage && !this->with_rht && !row_scaled_nvfp4) {
+        amax_columnwise = amax_rowwise;
+      } else {
+        amax_columnwise = at::empty({amax_cols}, bit32_tensor_opts);
+      }
     }
   }

@@ -2447,10 +2453,15 @@
       amax_columnwise.reset();
       tensor.attr("_amax_columnwise") = py::none();
     } else if (!amax_columnwise || amax_columnwise->numel() != amax_cols) {
-      const auto opts = at::TensorOptions().dtype(torch::kFloat32).device(torch::kCUDA);
-      // hadamard amax kernel will zero out pointer with ZeroAmaxKernel
-      // nvte_compute_amax_with_config will zero out the pointer if needed
-      amax_columnwise = at::empty({amax_cols}, opts);
+      if (rowwise_usage && amax_rowwise && !this->with_rht && !row_scaled_nvfp4) {
+        // PROTOTYPE (review of #3750): alias, as in create_tensor.
+        amax_columnwise = *amax_rowwise;
+      } else {
+        const auto opts = at::TensorOptions().dtype(torch::kFloat32).device(torch::kCUDA);
+        // hadamard amax kernel will zero out pointer with ZeroAmaxKernel
+        // nvte_compute_amax_with_config will zero out the pointer if needed
+        amax_columnwise = at::empty({amax_cols}, opts);
+      }
       tensor.attr("_amax_columnwise") = *amax_columnwise;
     }
   } else {  // columnwise_usage == false
